import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(const float* input, float* output, float constant, const float* bias, 
                               float scaling, int elements_per_channel, int C, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        val = fminf(val, constant);
        int c = (idx / elements_per_channel) % C;
        val += bias[c];
        val *= scaling;
        output[idx] = val;
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, float constant, torch::Tensor bias, float scaling) {
    auto out = torch::empty_like(input);
    int size = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int elements_per_channel = H * W;

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    fused_op_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), 
                                              constant, bias.data_ptr<float>(), scaling, 
                                              elements_per_channel, C, size);
    return out;
}
"""

fused_op_cpp_source = "torch::Tensor fused_op_cuda(torch::Tensor input, float constant, torch::Tensor bias, float scaling);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, constant_value, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.constant_value = constant_value
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor
        self.fused_op = fused_op

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_op.fused_op_cuda(x, self.constant_value, self.bias, self.scaling_factor)
        return x
